import struct,sys,zlib
def chunks(path):
    d=open(path,'rb').read()
    print("file",path,"len",len(d))
    print("sig",d[:8].hex())
    pos=8
    while pos<len(d):
        ln=struct.unpack('>I',d[pos:pos+4])[0]; typ=d[pos+4:pos+8]; data=d[pos+8:pos+8+ln]
        crc=d[pos+8+ln:pos+12+ln]
        calc=zlib.crc32(typ+data)&0xffffffff
        extra=''
        if typ==b'IHDR':
            w,h,bd,ct,cm,fl,il=struct.unpack('>IIBBBBB',data)
            extra=f"w={w} h={h} bitdepth={bd} colortype={ct} compression={cm} filter={fl} interlace={il}"
        elif typ==b'PLTE': extra=f"{ln//3} entries: "+' '.join(data[i:i+3].hex() for i in range(0,min(ln,60),3))
        elif typ==b'tRNS': extra=data.hex()
        elif typ==b'gAMA': extra=str(struct.unpack('>I',data)[0])
        elif typ in (b'tEXt',b'iTXt',b'zTXt'): extra=repr(data[:80])
        elif typ==b'IDAT': extra=f"(compressed data, first bytes {data[:4].hex()})"
        elif typ==b'pHYs': extra=str(struct.unpack('>IIB',data))
        elif typ==b'sBIT': extra=data.hex()
        elif typ==b'bKGD': extra=data.hex()
        elif typ==b'cHRM': extra=str(struct.unpack('>8I',data))
        elif typ==b'sRGB': extra=str(data[0])
        elif typ==b'iCCP': extra=repr(data[:40])
        print(f"  chunk {typ.decode('latin1')} len={ln} crcok={calc==struct.unpack('>I',crc)[0]} {extra}")
        pos+=12+ln
for p in sys.argv[1:]: chunks(p)
EOF
